// BroadcastChannel Cross-Tab Synchronization
if(typeof window!=="undefined"&&"BroadcastChannel" in window){
  try{
    const bc=new BroadcastChannel("ccmi_calibration_sync_channel");
    bc.onmessage=(ev)=>{
      if(ev.data?.type==="CALIBRATION_UPDATED"){
        window.dispatchEvent(new CustomEvent("medical_template_calibrated",{detail:{docType:ev.data.docType||"all"}}));
      }
    };
  }catch(e){}
}
// Purga preventiva de plantillas locales invalidas
if(typeof window!=="undefined"&&window.indexedDB){
  try{
    const r=window.indexedDB.open("SamirMoucharrafieTemplatesDB");
    r.onsuccess=function(e){
      try{
        const db=e.target.result;
        if(db.objectStoreNames.contains("official_stationery_templates")){
          const tx=db.transaction("official_stationery_templates","readwrite");
          const store=tx.objectStore("official_stationery_templates");
          const getReq=store.getAll();
          getReq.onsuccess=function(){
            const records=getReq.result||[];
            for(const rec of records){
              const validPdf=rec.originalPdfBytes&&rec.originalPdfBytes.length>100&&rec.originalPdfBytes[0]===37&&rec.originalPdfBytes[1]===80;
              const validUrl=rec.dataUrl&&(rec.dataUrl.startsWith("data:image/")||rec.dataUrl.startsWith("/templates/"));
              if(!validPdf&&!validUrl){
                store.delete(rec.docType);
              }
            }
          };
        }
      }catch(err){}
    };
  }catch(e){}
}
